//! Real companion process: a blocked local provider does not block acknowledged saves.
use serde_json::{json,Value};
use sha2::{Digest,Sha256};
use std::{io::{BufRead,BufReader,Read,Write},process::{Child,Command,Stdio},sync::mpsc,time::Duration};
struct Client {child:Child, output:mpsc::Receiver<Value>}
impl Client{
 fn new(path:&std::path::Path)->Self{let mut child=Command::new(env!("CARGO_BIN_EXE_novel-companion")).arg(path).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::null()).spawn().unwrap();let stdout=child.stdout.take().unwrap();let(tx,output)=mpsc::channel();std::thread::spawn(move||{for line in BufReader::new(stdout).lines(){let Ok(line)=line else{break};let Ok(value)=serde_json::from_str(&line)else{break};if tx.send(value).is_err(){break}}});Self{child,output}}
 fn send(&mut self,id:u64,op:&str,args:Value){let input=self.child.stdin.as_mut().unwrap();serde_json::to_writer(&mut *input,&json!({"id":id,"op":op,"args":args})).unwrap();input.write_all(b"\n").unwrap();input.flush().unwrap();}
 fn receive(&self)->Value{self.output.recv_timeout(Duration::from_secs(3)).expect("companion command timed out")}
 fn call(&mut self,id:u64,op:&str,args:Value)->Value{self.send(id,op,args);let value=self.receive();assert_eq!(value["id"],id);assert_eq!(value["ok"],true,"{value}");value["value"].clone()}
}
impl Drop for Client{fn drop(&mut self){let _=self.child.kill();let _=self.child.wait();}}
#[test]
fn native_sqlite_acknowledgement_arrives_while_provider_http_is_blocked(){
 let listener=std::net::TcpListener::bind("127.0.0.1:0").unwrap();let endpoint=format!("http://{}",listener.local_addr().unwrap());let(entered_tx,entered)=mpsc::channel();let(release,blocked)=mpsc::channel();
 let fake=std::thread::spawn(move||{let(mut socket,_)=listener.accept().unwrap();socket.set_read_timeout(Some(Duration::from_secs(3))).unwrap();let mut bytes=Vec::new();let mut buf=[0u8;4096];loop{let n=socket.read(&mut buf).unwrap();bytes.extend_from_slice(&buf[..n]);if let Some(end)=bytes.windows(4).position(|w|w==b"\r\n\r\n"){let h=String::from_utf8_lossy(&bytes[..end]);let length=h.lines().find_map(|l|l.to_ascii_lowercase().strip_prefix("content-length:").and_then(|s|s.trim().parse::<usize>().ok())).unwrap_or(0);if bytes.len()>=end+4+length{break}}}entered_tx.send(()).unwrap();let _=blocked.recv_timeout(Duration::from_secs(5));let body=json!({"model":"synthetic","choices":[{"message":{"content":"{\"suggestions\":[]}"}}]}).to_string();let _=socket.write_all(format!("HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",body.len()).as_bytes());});
 let directory=tempfile::tempdir().unwrap();let mut client=Client::new(directory.path());let p=client.call(1,"create_project",json!({"title":"Responsiveness fixture"}));let c=client.call(2,"create_chapter",json!({"projectId":p["id"],"title":"Chapter"}));let text="مَ 世界 😀";let scene=json!({"schemaVersion":1,"title":"Original","document":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":text}]}]}});let saved=client.call(3,"create_scene",json!({"chapterId":c["id"],"scene":scene}));let hash=format!("{:x}",Sha256::digest(text.as_bytes()));client.send(4,"provider_run",json!({"endpoint":endpoint,"runToken":"blocked:1","request":{"schemaVersion":1,"id":"blocked","projectId":p["id"],"provider":"llm","operation":"consistency","language":"ar","timeoutMs":5000,"sources":[{"sceneId":saved["id"],"revisionId":saved["revisionId"],"hash":hash,"text":text}]}}));entered.recv_timeout(Duration::from_secs(3)).expect("provider never reached the synthetic blocked HTTP endpoint");let mut next=scene;next["title"]=json!("Acknowledged during blocked provider");client.send(5,"save_scene",json!({"sceneId":saved["id"],"parent":saved["revisionId"],"requestId":"responsive-save","scene":next}));let response=client.receive();assert_eq!(response["id"],5,"provider completed before the blocked request was released: {response}");assert_eq!(response["ok"],true);let current=client.call(6,"load_scene",json!({"sceneId":saved["id"]}));assert_eq!(current["scene"]["title"],"Acknowledged during blocked provider");release.send(()).unwrap();let provider=client.receive();assert_eq!(provider["id"],4);assert_eq!(provider["ok"],true,"{provider}");fake.join().unwrap();
}
